INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Braucht eine Workstation immer mehr Leistung als ein Thin Client?', 2, '[{"text": "Ja", "correct": true, "because": "Lokale Verarbeitung vs. Serverabhängigkeit"}, {"text": "Nein", "correct": false, "because": "Selten umgekehrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware wähle ich für grafikintensive Aufgaben?', 3, '[{"text": "Workstation", "correct": true, "because": "Starke GPU und CPU nötig"}, {"text": "Thin Client", "correct": false, "because": "Abhängig von Serverleistung"}, {"text": "Standard-PC", "correct": false, "because": "Oft unterdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Workstation für CAD geeignet?', 5, '[{"text": "Hohe Rechenleistung", "correct": true, "because": "Komplexe Berechnungen"}, {"text": "Großer RAM", "correct": true, "because": "Große Modelle laden"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Sekundär"}, {"text": "Kleine Bauform", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Thin Clients sind kostengünstig. b) Workstations brauchen keine Netzwerkverbindung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Netzwerk oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Thin Clients?', 4, '[{"text": "Netzwerkanbindung", "correct": false, "because": "Kern der Funktion"}, {"text": "Serverkompatibilität", "correct": false, "because": "Muss passen"}, {"text": "High-End-GPU", "correct": true, "because": "Verarbeitung auf Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Workstation auch als Server dienen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Leistung ausreichend"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für einen Thin Client?', 3, '[{"text": "Geringe Anschaffungskosten", "correct": true, "because": "Wirtschaftlich sinnvoll"}, {"text": "Hohe lokale Leistung", "correct": false, "because": "Server übernimmt"}, {"text": "Großer Speicher", "correct": false, "because": "Nicht primär nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Workstation?', 5, '[{"text": "Hohe Leistung", "correct": true, "because": "Für anspruchsvolle Tasks"}, {"text": "Flexibilität", "correct": true, "because": "Lokale Anpassung möglich"}, {"text": "Geringere Kosten", "correct": false, "because": "Teurer als Thin Clients"}, {"text": "Einfache Verwaltung", "correct": false, "because": "Individuell komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Thin Clients sind wartungsarm. b) Workstations sind für einfache Aufgaben überdimensioniert. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) zentral verwaltet, b) oft zu stark"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Thin Client?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Serverzugriff", "correct": false, "because": "Kern der Nutzung"}, {"text": "Leistungsstarke CPU", "correct": true, "because": "Server übernimmt Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Workstations immer laut?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Kühlung ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen Thin Client in einem Callcenter wichtig?', 4, '[{"text": "Niedrige Kosten", "correct": true, "because": "Viele Geräte nötig"}, {"text": "Zentrale Verwaltung", "correct": true, "because": "Einfache Wartung"}, {"text": "Hohe lokale Speicherkapazität", "correct": false, "because": "Server speichert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Workstations keine Updates brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Software und Treiber aktuell halten"}, {"text": "Ja", "correct": false, "because": "Updates immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für eine Workstation im Designbereich?', 3, '[{"text": "Starke Grafikkarte", "correct": true, "because": "Rendering entscheidend"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Leistung wichtiger"}, {"text": "Kleine Bauform", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Thin Clients sind serverabhängig. b) Workstations sind für einfache Büroarbeiten ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft überdimensioniert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Thin Client?', 5, '[{"text": "Serverabhängigkeit", "correct": true, "because": "Ohne Server nutzlos"}, {"text": "Begrenzte lokale Leistung", "correct": true, "because": "Eingeschränkte Aufgaben"}, {"text": "Hohe Kosten", "correct": false, "because": "Eher günstiger"}, {"text": "Schwere Verwaltung", "correct": false, "because": "Zentral einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Workstation für Videoschnitt unwichtig?', 3, '[{"text": "RAM-Kapazität", "correct": false, "because": "Wichtig für große Dateien"}, {"text": "GPU-Leistung", "correct": false, "because": "Rendering entscheidend"}, {"text": "Minimale Lautstärke", "correct": true, "because": "Leistung hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Thin Clients für Gaming geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Lokale Leistung fehlt"}, {"text": "Ja", "correct": false, "because": "Nicht für grafikintensiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Workstation mobil sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Stationär oft ausreichend"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware wähle ich für zentrale Verwaltung?', 4, '[{"text": "Thin Client", "correct": true, "because": "Serverzentriert und einfach"}, {"text": "Workstation", "correct": false, "because": "Lokal unabhängig"}, {"text": "Standard-Laptop", "correct": false, "because": "Weniger zentralisiert"}]');
